'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getOrder from '@stdlib/ndarray-base-order';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import { ndarray as strided } from '@stdlib/blas-base-dspmv';


// MAIN //

/**
* Performs the matrix-vector operation `y = alpha*A*x + beta*y`, where `alpha` and `beta` are scalars, `x` and `y` are one-dimensional ndarrays, and `A` is an `N` by `N` symmetric matrix supplied in packed form.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray corresponding to the packed form of `A`.
*     -   a one-dimensional input ndarray corresponding to `x`.
*     -   a one-dimensional input/output ndarray corresponding to `y`.
*     -   a zero-dimensional ndarray specifying whether the upper or lower triangular part of `A` is supplied.
*     -   a zero-dimensional ndarray containing a scalar constant corresponding to `alpha`.
*     -   a zero-dimensional ndarray containing a scalar constant corresponding to `beta`.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
* import resolveEnum from '@stdlib/blas-base-matrix-triangle-resolve-enum';
*
* var AP = new Float64Vector( [ 1.0, 2.0, 3.0, 1.0, 2.0, 1.0 ] );
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Vector( [ 4.0, 5.0, 6.0 ] );
*
* var uplo = scalar2ndarray( resolveEnum( 'upper' ), {
*     'dtype': 'int32'
* });
* var alpha = scalar2ndarray( 3.0, {
*     'dtype': 'float64'
* });
* var beta = scalar2ndarray( 2.0, {
*     'dtype': 'float64'
* });
*
* var z = dspmv( [ AP, x, y, uplo, alpha, beta ] );
* // returns <ndarray>[ 50.0, 40.0, 42.0 ]
*
* var bool = ( z === y );
* // returns true
*/
function dspmv( arrays ) {
	var alpha;
	var uplo;
	var beta;
	var AP;
	var x;
	var y;

	AP = arrays[ 0 ];
	x = arrays[ 1 ];
	y = arrays[ 2 ];

	uplo = ndarraylike2scalar( arrays[ 3 ] );
	alpha = ndarraylike2scalar( arrays[ 4 ] );
	beta = ndarraylike2scalar( arrays[ 5 ] );

	strided( getOrder( AP ), uplo, numelDimension( x, 0 ), alpha, getData( AP ), getOffset( AP ), getData( x ), getStride( x, 0 ), getOffset( x ), beta, getData( y ), getStride( y, 0 ), getOffset( y ) ); // eslint-disable-line max-len

	return y;
}


// EXPORTS //

export default dspmv;
